from pathlib import Path
import json

task = json.loads(Path("input/task.json").read_text())
rows = task["rows"]
cols = task["cols"]
blocked = {tuple(cell) for cell in task.get("blocked", [])}
dp = [[0] * cols for _ in range(rows)]
for row in range(rows):
    for col in range(cols):
        if (row, col) in blocked:
            continue
        if row == 0 and col == 0:
            dp[row][col] = 1
        else:
            from_above = dp[row - 1][col] if row > 0 else 0
            from_left = dp[row][col - 1] if col > 0 else 0
            dp[row][col] = from_above + from_left
answer = dp[rows - 1][cols - 1] if rows > 0 and cols > 0 else 0
print(json.dumps(answer, sort_keys=True, separators=(",", ":")))

